// Trilho 1: recebe a amostra normalizada (100 ms) do fluxo de ingestão e atualiza o contexto global.
// NÃO publica: quem publica é o nó "consolidar" (uma mensagem única a cada 500 ms).
const s = msg.payload || {};
const st = s.stations || {};
const emergencia = s.buttons && s.buttons.emergency_pressed === true;
const flags = s.flags || {};
const pres = s.presence || {};

const telemetria = global.get('telemetria') || {
    timestamp: new Date().toISOString(),
    roboUR: { posicaoCartesiana: { x: 0, y: 0, z: 0 }, posicaoJuntas: [0, 0, 0, 0, 0, 0], garraFechada: false },
    esteira: { motorLigado: false, pecaAtual: null },
    estacoes: {
        estoque: { status: 'AGUARDANDO', magazine: 0 }, processo: { status: 'AGUARDANDO', magazine: 0 },
        montagem: { status: 'AGUARDANDO', magazine: 0 }, expedicao: { status: 'AGUARDANDO', magazine: 0 }
    },
    pedidoAtual: null
};

// Status do contrato (enum): EMERGENCIA > OPERANDO > AGUARDANDO.
// "segurancaOK = true" é o estado NORMAL da estação, então não indica operação; usamos esteira/ocupado.
function status(emerg, operando) { return emerg ? 'EMERGENCIA' : (operando ? 'OPERANDO' : 'AGUARDANDO'); }
const rodando = (e) => !!e && (e.esteira1 === true || e.esteira2 === true);

telemetria.estacoes.estoque   = { status: status(emergencia, flags.ocupado === true), magazine: 0 };
telemetria.estacoes.processo  = { status: status(emergencia, rodando(st.processo)),  magazine: 0 };
telemetria.estacoes.montagem  = { status: status(emergencia, rodando(st.montagem)),  magazine: 0 };
telemetria.estacoes.expedicao = { status: status(emergencia, rodando(st.expedicao)), magazine: 0 };
telemetria.esteira.motorLigado = s.belt_running === true;
// magazine, robô (roboUR) e peça atual não existem no mapa de tags do CLP: ficam nos valores padrão.

telemetria.timestamp = new Date().toISOString();
global.set('telemetria', telemetria);
return null;

// Só consulta o Elipse quando ELIPSE_ENABLED=true (evita erro de timeout no simulador).
if (env.get('ELIPSE_ENABLED') !== 'true') { return null; }
msg.url = env.get('ELIPSE_URL') || 'http://192.168.150.200:4321/api/Events/order/current';
return msg;

// Trilho 2: guarda o pedido atual no contexto global para o "consolidar" usar.
const telemetria = global.get('telemetria');
if (!telemetria) return null;
const p = msg.payload;
if (p && p.trackingCode) {
    telemetria.pedidoAtual = { trackingCode: p.trackingCode, componentId: p.componentId, status: p.status || 'EM_PRODUCAO' };
    global.set('telemetria', telemetria);
}
return null;

// Trilho 3: filtra eco, valida ação, origem e token. Saída 1 = comando válido, saída 2 = ack de rejeição.
if (typeof msg.payload === 'string') { try { msg.payload = JSON.parse(msg.payload); } catch (e) { return null; } }
const c = msg.payload;
if (!c || typeof c !== 'object') { return null; }
if (c.roboUR || c.tipo === 'ack') { return null; }   // eco de telemetria/ack
if (!c.acao) { return null; }

const ACOES = ['START', 'STOP', 'RESET', 'EMERGENCY_STOP'];
const ORIGENS = ['unidade1-grupo1', 'unidade1-grupo2', 'unidade1-grupo3', 'unidade1-grupo4', 'unidade1-grupo5'];
const nack = (motivo) => ({ payload: { tipo: 'ack', acao: c.acao, origem: c.origem || null, id: c.id || null,
    aceito: false, motivo: motivo, ts: new Date().toISOString() }, _session: msg._session });

if (!ACOES.includes(c.acao)) { return [null, nack('ação desconhecida')]; }

// EMERGENCY_STOP é sempre aceito: a segurança prevalece.
if (c.acao !== 'EMERGENCY_STOP') {
    if (!ORIGENS.includes(c.origem)) { node.warn('Comando rejeitado de origem: ' + c.origem); return [null, nack('origem não permitida')]; }
    const token = env.get('WS_TOKEN');
    if (token && c.token !== token) { node.warn('Token inválido de ' + c.origem); return [null, nack('token inválido')]; }
}
msg.comando = c;
return [msg, null];

// Aplica o comando. Saída 1 = simulador (link), saída 2 = ack para quem enviou.
// Projeto é SOMENTE LEITURA no CLP (docs/mapeamento-clp.md): fora do SIMULADOR nada é escrito.
const c = msg.comando;
const modo = env.get('INPUT_MODE') || 'SIMULADOR';
const ack = (ok, motivo) => ({ payload: { tipo: 'ack', acao: c.acao, origem: c.origem || null, id: c.id || null,
    aceito: ok, motivo: motivo || null, modo: modo, ts: new Date().toISOString() }, _session: msg._session });

if (modo !== 'SIMULADOR') { return [null, ack(false, 'modo ' + modo + ': CLP somente leitura, comando não escrito')]; }
const MAP = { START: 'START', STOP: 'STOP', RESET: 'RESET', EMERGENCY_STOP: 'EMERGENCY' };
return [{ topic: 'sim_cmd', payload: MAP[c.acao] }, ack(true)];

// Junta o estado global numa mensagem única e publica (broadcast para todos os clientes do /ws).
const telemetria = global.get('telemetria');
if (!telemetria) { return null; }   // ainda sem leitura
telemetria.timestamp = new Date().toISOString();
msg.payload = telemetria;
return msg;
